
CREATE SCHEMA [relacional]
go

CREATE TABLE [relacional].[apolice](
	[cd_apolice] [int] NOT NULL,
	[cd_cliente] [int] NOT NULL,
	[dt_inicio_vigencia] [datetime] NULL,
	[dt_fim_vigencia] [datetime] NULL,
	[vl_cobertura] [numeric](10, 2) NULL,
	[vl_franquia] [numeric](10, 2) NULL,
	[placa] [char](10) NULL
)
GO

CREATE TABLE [relacional].[carro](
	[placa] [char](10) NOT NULL,
	[cd_modelo] [int] NULL,
	[chassi] [varchar](30) NOT NULL,
	[ano] [int] NULL,
	[cor] [varchar](10) NULL
)
GO

CREATE TABLE [relacional].[cliente](
	[cd_cliente] [int] NOT NULL,
	[nome] [varchar](50) NULL,
	[cpf] [char](11) NOT NULL,
	[sexo] [char](1) NULL,
	[dt_nascimento] [date] NULL
)
GO

CREATE TABLE [relacional].[endereco](
	[cd_cliente] [int] NOT NULL,
	[cd_municipio] [int] NOT NULL,
	[ds_endereco] [varchar](200) NULL,
	[nr_endereco] [int] NULL,
	[bairro] [varchar](100) NULL,
 CONSTRAINT [pk_endereco] PRIMARY KEY ([cd_cliente] ASC)
)
GO

CREATE TABLE [relacional].[estado](
	[cd_estado] [int] NOT NULL,
	[cd_regiao] [int] NULL,
	[nm_estado] [varchar](50) NULL,
	[sigla_uf] [char](2) NULL,
 CONSTRAINT [pk_estado] PRIMARY KEY CLUSTERED ([cd_estado] ASC)
)
GO

CREATE TABLE [relacional].[marca](
	[cd_marca] [int] NOT NULL,
	[nm_marca] [varchar](100) NULL,
 CONSTRAINT [pk_marca] PRIMARY KEY ([cd_marca] ASC)
)
GO

CREATE TABLE [relacional].[modelo](
	[cd_modelo] [int] NOT NULL,
	[cd_marca] [int] NULL,
	[nm_modelo] [varchar](200) NULL,
 CONSTRAINT [pk_modelo] PRIMARY KEY ([cd_modelo] ASC)
)
GO

CREATE TABLE [relacional].[municipio](
	[cd_municipio] [int] NOT NULL,
	[nm_municipio] [varchar](100) NULL,
	[cd_estado] [int] NULL,
 CONSTRAINT [pk_municipio] PRIMARY KEY ([cd_municipio] ASC)
)
GO

CREATE TABLE [relacional].[regiao](
	[cd_regiao] [int] NOT NULL,
	[nm_regiao] [varchar](50) NULL,
    CONSTRAINT [pk_regiao] PRIMARY KEY ([cd_regiao] ASC)
)
GO

CREATE TABLE [relacional].[sinistro](
	[cd_sinistro] [int] NOT NULL,
	[placa] [char](10) NOT NULL,
	[dt_sinistro] [datetime] NULL,
	[local_sinistro] [int] NULL,
	[condutor] [varchar](50) NULL
)
GO

CREATE TABLE [relacional].[telefone](
	[cd_cliente] [int] NOT NULL,
	[nr_telefone] [varchar](11) NOT NULL,
    CONSTRAINT [pk_telefone] PRIMARY KEY ([cd_cliente] ASC, [nr_telefone] ASC)
)
GO

